ALTER TABLE users MODIFY role ENUM('admin','manager','viewer','technician','reporter','auditor') NOT NULL DEFAULT 'viewer';
CREATE TABLE IF NOT EXISTS suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(64) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL DEFAULT '',phone VARCHAR(40) NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT 1,version INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS assets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(64) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,room_id VARCHAR(100) NOT NULL,category VARCHAR(64) NOT NULL,serial VARCHAR(100) NOT NULL DEFAULT '',condition_status VARCHAR(32) NOT NULL,purchase_cost DECIMAL(12,2) NOT NULL DEFAULT 0,warranty_end DATE NULL,supplier_id BIGINT UNSIGNED NULL,active BOOLEAN NOT NULL DEFAULT 1,version INT NOT NULL DEFAULT 1,FOREIGN KEY(room_id) REFERENCES rooms(id),FOREIGN KEY(supplier_id) REFERENCES suppliers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS asset_moves(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,asset_id BIGINT UNSIGNED NOT NULL,old_room VARCHAR(100) NOT NULL,new_room VARCHAR(100) NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,reason VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(asset_id) REFERENCES assets(id),FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS contracts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(64) UNIQUE NOT NULL,title VARCHAR(150) NOT NULL,supplier_id BIGINT UNSIGNED NOT NULL,starts DATE NOT NULL,ends DATE NOT NULL,amount DECIMAL(12,2) NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,version INT NOT NULL DEFAULT 1,FOREIGN KEY(supplier_id) REFERENCES suppliers(id),CHECK(ends>=starts)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS parts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(64) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,unit VARCHAR(32) NOT NULL,reorder_level DECIMAL(12,3) NOT NULL DEFAULT 0,stock DECIMAL(12,3) NOT NULL DEFAULT 0,unit_cost DECIMAL(12,2) NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT 1,version INT NOT NULL DEFAULT 1,CHECK(stock>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sla_policies(priority VARCHAR(16) PRIMARY KEY,response_hours INT UNSIGNED NOT NULL,resolve_hours INT UNSIGNED NOT NULL,version INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO sla_policies(priority,response_hours,resolve_hours) VALUES('Tinggi',2,24),('Sederhana',8,72),('Rendah',24,168);
CREATE TABLE IF NOT EXISTS service_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,room_id VARCHAR(100) NOT NULL,asset_id BIGINT UNSIGNED NULL,created_by BIGINT UNSIGNED NOT NULL,subject VARCHAR(150) NOT NULL,description TEXT NOT NULL,priority VARCHAR(16) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'Baharu',reason VARCHAR(500) NOT NULL DEFAULT '',response_due DATETIME NOT NULL,resolve_due DATETIME NOT NULL,accepted_at DATETIME NULL,closed_at DATETIME NULL,version INT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(room_id) REFERENCES rooms(id),FOREIGN KEY(asset_id) REFERENCES assets(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS work_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id BIGINT UNSIGNED NULL,asset_id BIGINT UNSIGNED NULL,room_id VARCHAR(100) NOT NULL,title VARCHAR(150) NOT NULL,assigned_to BIGINT UNSIGNED NOT NULL,contract_id BIGINT UNSIGNED NULL,status VARCHAR(32) NOT NULL DEFAULT 'Ditugaskan',due_at DATETIME NOT NULL,checklist JSON NOT NULL,check_results JSON NULL,version INT NOT NULL DEFAULT 1,closed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES service_requests(id),FOREIGN KEY(asset_id) REFERENCES assets(id),FOREIGN KEY(room_id) REFERENCES rooms(id),FOREIGN KEY(assigned_to) REFERENCES users(id),FOREIGN KEY(contract_id) REFERENCES contracts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS work_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,work_order_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,minutes INT UNSIGNED NOT NULL,hourly_rate DECIMAL(12,2) NOT NULL,labor_cost DECIMAL(12,2) NOT NULL,note VARCHAR(2000) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(work_order_id) REFERENCES work_orders(id),FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,part_id BIGINT UNSIGNED NOT NULL,work_order_id BIGINT UNSIGNED NULL,actor_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(12,3) NOT NULL,unit_cost DECIMAL(12,2) NOT NULL,total_cost DECIMAL(12,2) NOT NULL,reason VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(part_id) REFERENCES parts(id),FOREIGN KEY(work_order_id) REFERENCES work_orders(id),FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS maintenance_plans(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,asset_id BIGINT UNSIGNED NOT NULL,assigned_to BIGINT UNSIGNED NOT NULL,interval_days INT UNSIGNED NOT NULL,next_due DATE NOT NULL,checklist JSON NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,version INT NOT NULL DEFAULT 1,FOREIGN KEY(asset_id) REFERENCES assets(id),FOREIGN KEY(assigned_to) REFERENCES users(id),CHECK(interval_days>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS maintenance_occurrences(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,plan_id BIGINT UNSIGNED NOT NULL,due_date DATE NOT NULL,work_order_id BIGINT UNSIGNED NOT NULL,UNIQUE KEY occurrence_once(plan_id,due_date),FOREIGN KEY(plan_id) REFERENCES maintenance_plans(id),FOREIGN KEY(work_order_id) REFERENCES work_orders(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bookings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,room_id VARCHAR(100) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(150) NOT NULL,starts DATETIME NOT NULL,ends DATETIME NOT NULL,attendees INT UNSIGNED NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'Menunggu',reason VARCHAR(500) NOT NULL DEFAULT '',version INT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(room_id) REFERENCES rooms(id),FOREIGN KEY(user_id) REFERENCES users(id),KEY booking_window(room_id,starts,ends),CHECK(ends>starts)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS room_charges(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,room_id VARCHAR(100) NOT NULL,period CHAR(7) NOT NULL,area_snapshot DECIMAL(12,4) NOT NULL,rate DECIMAL(12,2) NOT NULL,amount DECIMAL(12,2) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY room_charge_once(room_id,period),FOREIGN KEY(room_id) REFERENCES rooms(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS budgets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,period CHAR(7) UNIQUE NOT NULL,amount DECIMAL(12,2) NOT NULL,note VARCHAR(500) NOT NULL DEFAULT '',version INT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS meters(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(64) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,room_id VARCHAR(100) NOT NULL,unit VARCHAR(32) NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,version INT NOT NULL DEFAULT 1,FOREIGN KEY(room_id) REFERENCES rooms(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS meter_readings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,meter_id BIGINT UNSIGNED NOT NULL,recorded_at DATETIME NOT NULL,value DECIMAL(16,3) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,UNIQUE KEY reading_once(meter_id,recorded_at),FOREIGN KEY(meter_id) REFERENCES meters(id),FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,message VARCHAR(500) NOT NULL,entity_type VARCHAR(32) NOT NULL,entity_id VARCHAR(100) NOT NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS attachments(id VARCHAR(64) PRIMARY KEY,entity_type VARCHAR(32) NOT NULL,entity_id VARCHAR(100) NOT NULL,original_name VARCHAR(200) NOT NULL,mime VARCHAR(80) NOT NULL,size_bytes INT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
